{
  "analysis": "The required tools are now installed: ffmpeg, ffprobe, python3, tesseract, and convert are all available. I can now inspect the video metadata and extract frames to transcribe the Zork text.",
  "plan": "Get video duration/resolution/frame rate with ffprobe. Extract a few sample frames to understand the terminal appearance, then run OCR on a sample frame to assess text extraction quality.",
  "commands": [
    {
      "keystrokes": "ffprobe -v error -show_entries stream=index,codec_type,width,height,r_frame_rate,duration -show_entries format=duration -of default /app/video.mp4\n",
      "duration": 1.0
    },
    {
      "keystrokes": "mkdir -p /app/frames && ffmpeg -y -i /app/video.mp4 -vf \"select='eq(n\\,0)+eq(n\\,30)+eq(n\\,60)'\" -vsync vfr -q:v 2 /app/frames/sample_%03d.png\n",
      "duration": 1.0
    },
    {
      "keystrokes": "ls -la /app/frames && for f in /app/frames/*.png; do echo \"=== $f ===\"; tesseract \"$f\" stdout --psm 6 2>/dev/null | head -40; done\n",
      "duration": 1.0
    }
  ]
}
